    nop
record_publish_begin:
    ld $t0, 80($sp)
    daddiu $t0, $t0, 1
    sd $t0, 8($s3)
    sd $s4, 24($s3)
    li $v1, 16384
    sd $v1, 32($s3)
    move $v0, $zero
record_published:
